export default (async () => {
type RenderFn = (result: unknown, ctx: BlockContext) => RenderResult;

interface BlockContext {
  language: string;
  code: string;
  blockIndex: number;
  blockName?: string;
  parameters: Record<string, string>;
}

interface RenderResult {
  html: string;
  css?: string;
  js?: string;
}

})();